'use strict';
(()=>{
 const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const skills=[
 {name:'Microsoft Azure',re:/\b(?:azure|az-900)\b/,level:1,weight:3,confidence:'Alta',evidence:'Atuação com Azure desde 2019 e certificação Microsoft Certified: Azure Fundamentals (AZ-900).',link:'#certificados',category:'Cloud'},
 {name:'.NET / C#',re:/(?:\.net|dotnet|c#|csharp)/,level:.95,weight:2,confidence:'Alta',evidence:'Desenvolvimento de APIs e serviços .NET na Reply desde 2019.',link:'#experiencia',category:'Backend'},
 {name:'React',re:/\breact(?:js|\.js)?\b/,level:.9,weight:1,confidence:'Alta',evidence:'Interfaces React e uso de hooks na atuação full stack.',link:'#experiencia',category:'Frontend'},
 {name:'Vue / Nuxt',re:/\b(?:vue|nuxt)(?:js|\.js)?\b/,level:.9,weight:1,confidence:'Alta',evidence:'Desenvolvimento de interfaces Vue.js e Nuxt.',link:'#experiencia',category:'Frontend'},
 {name:'Node.js',re:/\bnode(?:\.?js)?\b/,level:.85,weight:1,confidence:'Alta',evidence:'Desenvolvimento backend com Node.js na atuação sênior.',link:'#experiencia',category:'Backend'},
 {name:'NestJS',re:/\bnest(?:js|\.js)?\b/,level:.6,weight:1,confidence:'Média',evidence:'NestJS declarado no conjunto de competências; profundidade a confirmar em conversa técnica.',link:'#certificados',category:'Backend'},
 {name:'APIs REST',re:/\b(?:apis?|rest|restful)\b/,level:.95,weight:2,confidence:'Alta',evidence:'Desenvolvimento e integração de APIs e serviços entre aplicações.',link:'#pratica',category:'Integrações'},
 {name:'Kafka / Eventos',re:/\b(?:kafka|eventos?|event.driven|mensageria)\b/,level:.85,weight:2,confidence:'Média',evidence:'Experiência declarada em arquitetura orientada a eventos e mensageria com Kafka.',link:'#pratica',category:'Integrações'},
 {name:'Webhooks',re:/\bwebhooks?\b/,level:.85,weight:1,confidence:'Média',evidence:'Desenvolvimento de webhooks para integração de sistemas.',link:'#pratica',category:'Integrações'},
 {name:'SQL / Dados',re:/\b(?:sql|postgresql|oracle|bancos? de dados|database)\b/,level:.95,weight:1,confidence:'Alta',evidence:'Trajetória com SQL Server desde 2016 e experiência com PostgreSQL e Oracle.',link:'#experiencia',category:'Dados'},
 {name:'Claude Code e Codex',re:/\b(?:claude|codex|agentes? de (?:codigo|ia)|inteligencia artificial|ia|ai)\b/,level:.85,weight:1,confidence:'Média',evidence:'Uso de Claude Code e Codex no desenvolvimento orientado por especificações, com revisão e validação.',link:'#ia',category:'IA & SDD'},
 {name:'SDD / OpenSpec',re:/\b(?:sdd|openspec|spec.driven|especificacoes)\b/,level:.85,weight:1,confidence:'Média',evidence:'OpenSpec: proposal, delta specs, design, tasks e verificação dos cenários de aceitação.',link:'#ia',category:'IA & SDD'},
 {name:'Angular',re:/\bangular\b/,level:.8,weight:1,confidence:'Alta',evidence:'Angular integra a experiência frontend declarada.',link:'#certificados',category:'Frontend'},
 {name:'Inglês',re:/\b(?:ingles|english)\b/,level:.9,weight:1,confidence:'Média',evidence:'Inglês avançado declarado no currículo.',link:'#perguntas',category:'Comunicação'},
 ...[['Kubernetes',/\b(?:kubernetes|k8s)\b/],['Docker',/\bdocker\b/],['Terraform',/\bterraform\b/],['Python',/\bpython\b/],['AWS em produção',/\baws\b/],['Liderança formal',/\b(?:lideranca|tech lead|gestao de pessoas)\b/]].map(([name,re])=>({name,re,level:name==='AWS em produção'?.25:0,weight:1,confidence:'A confirmar',evidence:name==='AWS em produção'?'Curso preparatório de AWS comprovado; atuação em produção a confirmar.':'Sem evidência detalhada no currículo atual; confirmar em entrevista.',link:'#certificados',category:'A confirmar'}))
 ];
 const input=document.querySelector('#job'),out=document.querySelector('#fit-output');
 const draft='Desenvolvedor Sênior Full Stack com foco em Azure\nBuscamos experiência em Microsoft Azure, C# e .NET, APIs REST, React ou Vue e SQL Server. Integrações orientadas a eventos com Kafka e webhooks. Desenvolvimento com IA usando Claude Code e Codex, SDD e OpenSpec.\nDesejável: Kubernetes em produção.';
 const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
 function analyze(){document.querySelector('#fit-empty').hidden=true;out.hidden=false;out.replaceChildren();const text=normalize(input.value);const results=skills.filter(s=>s.re.test(text)).map(s=>{const sentences=text.split(/[\n.!;]+/).filter(x=>s.re.test(x));const optional=sentences.every(x=>/desejavel|diferencial|opcional|nice.to.have/.test(x));return {...s,optional,w:s.weight*(optional?.5:1)};});
 if(!results.length){out.append(el('p','empty-match','Inclua requisitos ou tecnologias na descrição para visualizar a aderência.'));document.querySelector('#analysis-steps').textContent='Aguardando requisitos reconhecidos.';return;}
 const total=results.reduce((a,s)=>a+s.w,0),score=Math.round(results.reduce((a,s)=>a+s.w*s.level,0)/total*100),high=results.filter(s=>s.confidence==='Alta').length;
 const summary=el('div','fit-summary');const ring=el('div','score-ring');ring.style.setProperty('--score',score+'%');ring.setAttribute('role','img');ring.setAttribute('aria-label',`Aderência estimada: ${score} de 100`);const inside=el('div');inside.append(el('strong','',score),el('span','','/100 FIT'));ring.append(inside);
 const copy=el('div','score-copy');copy.append(el('span','recommend-tag','● ADERÊNCIA ESTIMADA'),el('h3','',score>=75?'Bom alinhamento para uma conversa técnica':score>=45?'Alinhamento parcial com a vaga':'Explorar os requisitos em entrevista'),el('span','confidence-tag',`EVIDÊNCIA ALTA EM ${high} DE ${results.length} REQUISITOS`));
 const confirmed=results.filter(s=>s.level>=.8).slice(0,4).map(s=>s.name),pending=results.filter(s=>s.level<.8).map(s=>s.name);copy.append(el('p','',`${confirmed.length?'Destaques: '+confirmed.join(', ')+'. ':''}${pending.length?'A confirmar: '+pending.join(', ')+'.':''}`));summary.append(ring,copy);out.append(summary);
 const chart=el('div','category-chart');chart.append(el('span','eyebrow','COBERTURA POR ÁREA'));const categories=[...new Set(results.map(s=>s.category))];categories.forEach(c=>{const rs=results.filter(s=>s.category===c),v=Math.round(rs.reduce((a,s)=>a+s.level*s.w,0)/rs.reduce((a,s)=>a+s.w,0)*100);const row=el('div','category-row'),track=el('span','category-track'),fill=el('span');fill.style.width=v+'%';track.append(fill);row.append(el('span','',c),track,el('b','',v+'%'));chart.append(row);});out.append(chart);
 const table=el('table','fit-table'),thead=el('thead'),hr=el('tr');['Requisito','Nível','Evidência','Confiança'].forEach(t=>hr.append(el('th','',t)));thead.append(hr);const tbody=el('tbody');results.forEach(s=>{const tr=el('tr'),req=el('td');req.append(el('b','',s.name),el('small','',`${s.optional?'DESEJÁVEL':'REQUISITO'} · PESO ${s.w}`));const level=el('td'),bars=el('div','level-bars');bars.setAttribute('aria-label',`${Math.round(s.level*100)}% de cobertura estimada`);for(let i=0;i<4;i++)bars.append(el('i',i<Math.round(s.level*4)?'filled':''));level.append(bars,el('small','',s.level>=.98?'Domínio':s.level>=.8?'Forte':s.level>0?'Parcial':'A confirmar'));const evidence=el('td','evidence-text',s.evidence),link=el('a','','Ver evidência ↗');link.href=s.link;evidence.append(link);tr.append(req,level,evidence,el('td',s.confidence==='Alta'?'confidence-high':'confidence-medium',s.confidence));tbody.append(tr);});table.append(thead,tbody);const scroll=el('div','fit-table-scroll');scroll.append(table);out.append(scroll);
 out.append(el('p','micro methodology','Nota = média ponderada da cobertura declarada. Azure recebe peso 3 por atuação desde 2019 e certificação; .NET, REST e Kafka recebem peso 2. Requisitos desejáveis têm metade do peso. Outros requisitos não reconhecidos precisam de avaliação humana.'));
 document.querySelector('#analysis-steps').textContent=`✓ ${results.length} requisitos reconhecidos (${results.filter(s=>!s.optional).length} principais · ${results.filter(s=>s.optional).length} desejáveis)\n✓ Comparados com experiência e comprovantes\n✓ Nota ponderada atualizada em tempo real`;
 }
 document.querySelectorAll('.context-chips button').forEach(b=>b.addEventListener('click',()=>b.setAttribute('aria-pressed',String(b.getAttribute('aria-pressed')!=='true'))));
 document.querySelector('#example').addEventListener('click',()=>{input.value=draft;analyze();input.focus();});document.querySelector('#fit-form').addEventListener('submit',e=>{e.preventDefault();analyze();});input.addEventListener('input',analyze);input.value=draft;analyze();
})();
